<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Api\BaseApiController; use App\Models\{Product,ProductVariant}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ProductController extends BaseApiController { public function index(){return $this->ok(Product::with(['category','variants'])->orderBy('sort_order')->latest()->get());} public function show(Product $product){return $this->ok($product->load(['category','variants']));} public function store(Request $r){return $this->save($r);} public function update(Request $r,Product $product){return $this->save($r,$product);} public function destroy(Product $product){$product->delete();return $this->ok();} private function save(Request $r,?Product $product=null){$d=$r->validate(['legacy_id'=>'nullable|string|max:190','name'=>'required|string|max:255','slug'=>'required|string|max:255','description'=>'nullable|string','image_url'=>'nullable|string','gallery_urls'=>'nullable|array','old_price'=>'nullable|numeric','price'=>'required|numeric|min:0','stock_quantity'=>'required|integer|min:0','sold_quantity'=>'nullable|integer|min:0','discount_percent'=>'nullable|numeric','is_featured'=>'boolean','is_flash_sale'=>'boolean','is_hot_deal'=>'boolean','is_active'=>'boolean','sort_order'=>'integer','category_id'=>'nullable|string','variants'=>'nullable|array']);return DB::transaction(function()use($d,$product){$product?->update($d) ?: $product=Product::create($d);if(array_key_exists('variants',$d)){ $product->variants()->delete();foreach($d['variants'] as $i=>$v)$product->variants()->create(['label'=>$v['label'],'weight_grams'=>$v['weight_grams']??null,'price'=>$v['price']??0,'old_price'=>$v['old_price']??null,'stock_quantity'=>$v['stock_quantity']??0,'is_active'=>$v['is_active']??true,'sort_order'=>$v['sort_order']??$i]);}return $this->ok($product->load('variants'),$product->wasRecentlyCreated?201:200);});} }
